return {api_version=1,id="CS2_104",name="Rampage",text="Give a damaged minion +3/+3.",set="EXPERT1",type="spell",class="warrior",rarity="common",cost=2,target_mode="required",targets=function(ctx)local r={};for _,e in ipairs(ctx:minions())do if ctx:entity(e).damage>0 then r[#r+1]=e end end;return r end,on_play=function(ctx,self,target)ctx:buff(target,3,3)end}
